// NodeConfig **冻结契约：裸对象，不套信封。** 字段随 `protocol` 分支不同而不同（VLESS+REALITY / Hysteria2 …），
// 因此全部 optional 且允许附加字段。
//
// **新增字段的规则**：我们自己需要的字段一律加在顶层新键，且**必须做到「v2node 忽略它也能正常工作」**
// （Go 的 `encoding/json` 默认忽略未知字段，但仍需在契约测试里断言）。
// 任何「节点必须理解才能工作」的新字段 = 破坏性变更。
//
// > 🔴 **必须显式记录的缺口**：已裁定「证书必须钉 Let's Encrypt，禁用 Google Trust Services」，
// > 但 Xboard 的 hysteria 分支**是否有证书相关字段，调研中没有记录 —— 需核实**。
// > 若契约里没有位置，证书只能在装机脚本层面固定（certbot + LE），不经 `/config` 下发 ——
// > 两者的 runbook 完全不同。
type NodeConfig struct {
	// BaseConfig v2node 的 `BaseConfig` 块。
	BaseConfig *NodeBaseConfig `json:"base_config,omitempty"`

	// DownMbps 🔴 同 `up_mbps`，必须下发 `0`。
	DownMbps *int32 `json:"down_mbps,omitempty"`

	// Flow 例 `xtls-rprx-vision`
	Flow     *string `json:"flow,omitempty"`
	ListenIp *string `json:"listen_ip,omitempty"`
	Network  *string `json:"network,omitempty"`

	// NetworkSettings 照抄 Xboard 的驼峰键名 —— **不改名**，即使它与周围的蛇形命名不一致。
	NetworkSettings *map[string]interface{} `json:"networkSettings,omitempty"`

	// Obfs 例 `salamander`
	Obfs *string `json:"obfs,omitempty"`

	// ObfsPassword 照抄 Xboard 的连字符键名 —— **不改名**。
	ObfsPassword *string `json:"obfs-password,omitempty"`

	// Protocol `vless` / `hysteria` / `shadowsocks` …
	Protocol   *string `json:"protocol,omitempty"`
	ServerName *string `json:"server_name,omitempty"`
	ServerPort *int32  `json:"server_port,omitempty"`

	// Tls `0` 无 / `1` TLS / `2` REALITY
	Tls *int32 `json:"tls,omitempty"`

	// TlsSettings REALITY / TLS 参数，照抄 Xboard `buildNodeConfig()`。**不改名、不改类型。**
	TlsSettings *NodeTlsSettings `json:"tls_settings,omitempty"`

	// UpMbps 🔴 **Hysteria 分支必须下发 `0`。** 这与 `down_mbps` 正是 **Brutal 拥塞控制的参数**，
	// 已裁定「Hysteria2 用 BBR 不用 Brutal」，所以必须下发 0（= 不声明带宽 = 不启用 Brutal）。
	// **v2node 对 0 的处理 需实测。**
	UpMbps *int32 `json:"up_mbps,omitempty"`

	// Version Hysteria 分支用（`2`）。
	Version              *int32                 `json:"version,omitempty"`
	AdditionalProperties map[string]interface{} `json:"-"`
}

// NodeError **节点面的错误形状，不套统一信封**（v2node 用 Go 结构体直接反序列化，包一层 `{"data":…}` 立刻不兼容）。
